package com.wellcheck.service;
import com.wellcheck.dto.ApiDtos.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class OperationalService {
 private final JdbcTemplate jdbc; private final AuditService audit; public OperationalService(JdbcTemplate j,AuditService a){jdbc=j;audit=a;}
 private UUID actor(Authentication a){return UUID.fromString(a.getName());}
 private Map<String,Object> row(java.sql.ResultSet r,int n)throws java.sql.SQLException{Map<String,Object> x=new LinkedHashMap<>();x.put("id",r.getObject("id").toString());x.put("title",r.getString("title"));x.put("category",r.getString("category"));x.put("status",r.getString("status"));x.put("priority",r.getString("priority"));x.put("latitude",r.getObject("latitude"));x.put("longitude",r.getObject("longitude"));x.put("createdAt",String.valueOf(r.getObject("created_at")));return x;}
 public Map<String,Object> createReport(Authentication a,ReportCreate in){UUID id=UUID.randomUUID();String ref="WC-"+Instant.now().toEpochMilli()+"-"+id.toString().substring(0,5).toUpperCase();jdbc.update("INSERT INTO reports(id,reference_no,reporter_id,category,description,location,location_label) VALUES(?,?,?,?,?,CASE WHEN ? IS NULL THEN NULL ELSE ST_SetSRID(ST_MakePoint(?,?),4326)::geography END,?)",id,ref,actor(a),in.category(),in.description(),in.latitude(),in.longitude(),in.latitude(),in.locationLabel());jdbc.update("INSERT INTO report_status_history(report_id,new_status,changed_by,note) VALUES(?,'SUBMITTED',?,?)",id,actor(a),"Report submitted");audit.record(a,"REPORT_CREATED","report",id);return Map.of("id",id,"referenceNo",ref,"status","SUBMITTED");}
 public List<Map<String,Object>> myReports(Authentication a){return jdbc.queryForList("SELECT id,reference_no AS \"referenceNo\",category,status,description,location_label AS \"locationLabel\",created_at AS \"createdAt\" FROM reports WHERE reporter_id=? ORDER BY created_at DESC",actor(a));}
 public List<Map<String,Object>> adminReports(){return jdbc.queryForList("SELECT r.id,r.reference_no AS \"referenceNo\",r.category,r.status,r.description,r.location_label AS \"locationLabel\",r.created_at AS \"createdAt\",u.display_name AS \"reporterName\" FROM reports r JOIN users u ON u.id=r.reporter_id ORDER BY r.created_at DESC");}
 public void reviewReport(Authentication a,UUID id,Review in){if(!Set.of("UNDER_REVIEW","VERIFIED","REJECTED","ASSIGNED","IN_PROGRESS","RESOLVED").contains(in.status()))throw new IllegalArgumentException("Invalid report status");if("REJECTED".equals(in.status())&&(in.note()==null||in.note().isBlank()))throw new IllegalArgumentException("A rejection explanation is required");jdbc.update("UPDATE reports SET status=?,reviewer_note=?,updated_at=now() WHERE id=?",in.status(),in.note(),id);jdbc.update("INSERT INTO report_status_history(report_id,new_status,note,changed_by) VALUES(?,?,?,?)",id,in.status(),in.note(),actor(a));audit.record(a,"REPORT_REVIEWED","report",id);}
 public Map<String,Object> createIncident(Authentication a,IncidentCreate in){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO incidents(id,title,category,priority,location) VALUES(?,?,?,?,CASE WHEN ? IS NULL THEN NULL ELSE ST_SetSRID(ST_MakePoint(?,?),4326)::geography END)",id,in.title(),in.category(),in.priority(),in.latitude(),in.longitude(),in.latitude());audit.record(a,"INCIDENT_CREATED","incident",id);return Map.of("id",id);}
 public List<Map<String,Object>> incidents(){return jdbc.query("SELECT id,title,category,status,priority,verified,ST_Y(location::geometry) latitude,ST_X(location::geometry) longitude,created_at FROM incidents ORDER BY created_at DESC",this::row);}
 public void verifyIncident(Authentication a,UUID id){jdbc.update("UPDATE incidents SET verified=true,updated_at=now() WHERE id=?",id);jdbc.update("INSERT INTO incident_status_history(incident_id,status,note,changed_by) VALUES(?,'VERIFIED','Verified by authorised administrator',?)",id,actor(a));audit.record(a,"INCIDENT_VERIFIED","incident",id);}
 public List<Map<String,Object>> markers(){return jdbc.queryForList("SELECT id,title,category,status,priority,verified,ST_Y(location::geometry) AS latitude,ST_X(location::geometry) AS longitude FROM incidents WHERE location IS NOT NULL");}
 public List<Map<String,Object>> centres(){return jdbc.queryForList("SELECT id,name,address,contact,capacity,available_beds AS \"availableBeds\",operational,ST_Y(location::geometry) AS latitude,ST_X(location::geometry) AS longitude FROM relief_centres ORDER BY name");}
 public Map<String,Object> createCentre(Authentication a,CentreCreate in){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO relief_centres(id,name,address,contact,capacity,available_beds,location) VALUES(?,?,?,?,?,?,CASE WHEN ? IS NULL THEN NULL ELSE ST_SetSRID(ST_MakePoint(?,?),4326)::geography END)",id,in.name(),in.address(),in.contact(),in.capacity(),in.availableBeds(),in.latitude(),in.longitude(),in.latitude());audit.record(a,"RELIEF_CENTRE_CREATED","relief_centre",id);return Map.of("id",id);}
 public List<Map<String,Object>> teams(){return jdbc.queryForList("SELECT id,name,capabilities,availability,ST_Y(location::geometry) AS latitude,ST_X(location::geometry) AS longitude FROM rescue_teams ORDER BY name");}
 public Map<String,Object> createTeam(Authentication a,TeamCreate in){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO rescue_teams(id,name,capabilities,location) VALUES(?,?,?,CASE WHEN ? IS NULL THEN NULL ELSE ST_SetSRID(ST_MakePoint(?,?),4326)::geography END)",id,in.name(),in.capabilities(),in.latitude(),in.longitude(),in.latitude());audit.record(a,"RESCUE_TEAM_CREATED","rescue_team",id);return Map.of("id",id);}
 public Map<String,Object> assign(Authentication a,AssignmentCreate in){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO rescue_assignments(id,incident_id,team_id,detail) VALUES(?,?,?,?)",id,in.incidentId(),in.teamId(),in.detail());jdbc.update("UPDATE rescue_teams SET availability='ASSIGNED',updated_at=now() WHERE id=?",in.teamId());audit.record(a,"RESCUE_ASSIGNED","rescue_assignment",id);return Map.of("id",id,"status","ASSIGNED");}
 public List<Map<String,Object>> alerts(){return jdbc.queryForList("SELECT id,title,body,severity,status,expires_at AS \"expiresAt\",created_at AS \"createdAt\" FROM alerts WHERE status='PUBLISHED' AND (expires_at IS NULL OR expires_at>now()) ORDER BY created_at DESC");}
 public Map<String,Object> createAlert(Authentication a,AlertCreate in){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO alerts(id,title,body,severity,expires_at,created_by) VALUES(?,?,?,?,cast(? as timestamptz),?)",id,in.title(),in.body(),in.severity(),in.expiresAt(),actor(a));audit.record(a,"ALERT_CREATED","alert",id);return Map.of("id",id,"status","DRAFT");}
 public void publishAlert(Authentication a,UUID id){jdbc.update("UPDATE alerts SET status='PUBLISHED',updated_at=now() WHERE id=?",id);audit.record(a,"ALERT_PUBLISHED","alert",id);}
 public List<Map<String,Object>> sources(){return jdbc.queryForList("SELECT id,name,source_type AS \"sourceType\",configured,health,last_success_at AS \"lastSuccessAt\",last_error AS \"lastError\" FROM data_sources ORDER BY name");}
}

